# %% [markdown]
# ## Step 7 — Bulk Evaluation: Run All 10 Tickets Through Both Variants
#
# Now run the full corpus through both variants and collect scores. This will take ~1-2 minutes as each ticket is scored 4 times (2 variants × 2 criteria per ticket).

# %%
import statistics

async def score_ticket(ticket, variant_name, system_prompt):
    """Run a ticket through a variant and score it."""
    # Step 1: Generate response
    gen_resp = await lrn_llm.call(
        [{"role": "user", "content": ticket["input"]}],
        system=system_prompt,
        max_tokens=300
    )
    output = lrn_llm.text(gen_resp)
    
    # Step 2: Score response
    judge_prompt = f"""Support question: {ticket['input']}

Support response: {output}

Reference answer: {ticket['reference']}

{JUDGE_RUBRIC}"""
    
    judge_resp = await lrn_llm.call(
        [{"role": "user", "content": judge_prompt}],
        max_tokens=300
    )
    judge_text = lrn_llm.text(judge_resp)
    
    # Step 3: Parse scores
    try:
        scores = json.loads(judge_text)
        avg_score = (scores["relevance"] + scores["correctness"] + scores["helpfulness"] + scores["completeness"]) / 4
        return {
            "ticket_id": ticket["id"],
            "variant": variant_name,
            "output": output[:100],  # truncate for display
            "scores": scores,
            "avg_score": avg_score
        }
    except:
        return {
            "ticket_id": ticket["id"],
            "variant": variant_name,
            "output": output[:100],
            "scores": {"error": "parse failed"},
            "avg_score": 0
        }

print("Running evaluation on 10 tickets × 2 variants...")
results = []

for ticket in TICKETS:
    print(f"  Processing {ticket['id']}...", end="", flush=True)
    r_a = await score_ticket(ticket, "Variant A (Terse)", VARIANT_A)
    r_b = await score_ticket(ticket, "Variant B (Detailed)", VARIANT_B)
    results.append(r_a)
    results.append(r_b)
    print(f" A={r_a['avg_score']:.2f}, B={r_b['avg_score']:.2f}")

print(f"\n✅ Evaluation complete. {len(results)} results collected.")

# %% [markdown]
# ## Step 8 — Aggregate Scores and Compare
#
# Now aggregate the results by variant and compare: did Variant B actually improve, or does the data show no significant difference?

# %%
# Separate results by variant
results_a = [r for r in results if r["variant"] == "Variant A (Terse)"]
results_b = [r for r in results if r["variant"] == "Variant B (Detailed)"]

# Collect individual criterion scores
def collect_criterion_scores(result_list, criterion):
    scores = []
    for r in result_list:
        if criterion in r["scores"]:
            scores.append(r["scores"][criterion])
    return scores

criteria = ["relevance", "correctness", "helpfulness", "completeness"]
print("\n" + "="*70)
print("  VARIANT COMPARISON REPORT")
print("="*70)

comparison = {}
for criterion in criteria:
    scores_a = collect_criterion_scores(results_a, criterion)
    scores_b = collect_criterion_scores(results_b, criterion)
    
    if scores_a and scores_b:
        mean_a = statistics.mean(scores_a)
        mean_b = statistics.mean(scores_b)
        diff = mean_b - mean_a
        
        comparison[criterion] = {
            "mean_a": mean_a,
            "mean_b": mean_b,
            "diff": diff,
            "scores_a": scores_a,
            "scores_b": scores_b
        }
        
        trend = "↑ improved" if diff > 0.3 else ("↓ regressed" if diff < -0.3 else "= stable")
        print(f"  {criterion:15} A={mean_a:.2f} → B={mean_b:.2f} (diff: {diff:+.2f}) {trend}")

# Overall
overall_a = [r["avg_score"] for r in results_a]
overall_b = [r["avg_score"] for r in results_b]
if overall_a and overall_b:
    overall_mean_a = statistics.mean(overall_a)
    overall_mean_b = statistics.mean(overall_b)
    overall_diff = overall_mean_b - overall_mean_a
    print(f"\n  Overall:        A={overall_mean_a:.2f} → B={overall_mean_b:.2f} (diff: {overall_diff:+.2f})")

print("="*70)

# %% [markdown]
# ## Step 9 — Ship/Block Decision
#
# Based on the LLM-as-judge scores, make a ship/block recommendation. The rule:
#
# - **SHIP** Variant B if overall score improves by >0.3 on average and no criterion regresses significantly.
# - **HOLD** if change is negligible (diff within ±0.3).
# - **BLOCK** Variant B if any criterion drops significantly or overall score regresses.

# %%
# Decision logic
regressions = [c for c in comparison if comparison[c]["diff"] < -0.3]
improvements = [c for c in comparison if comparison[c]["diff"] > 0.3]

if overall_diff > 0.3 and not regressions:
    decision = "SHIP Variant B"
    reasoning = f"Overall improvement of {overall_diff:.2f}/5, improvements in {improvements}."
elif overall_diff < -0.3 or regressions:
    decision = "BLOCK Variant B"
    reasoning = f"Regression detected: {regressions}. Revert to Variant A."
else:
    decision = "HOLD"
    reasoning = f"Change is negligible (diff {overall_diff:+.2f}). Requires manual review."

print(f"\nDecision: {decision}")
print(f"Reasoning: {reasoning}")
print(f"\nMetrics summary:")
print(f"  Improvements: {improvements}")
print(f"  Regressions: {regressions}")
print(f"  Test cases: {len(results_a)} samples per variant")

